// ─────────────────────────────────────────────────────────────────────────────
// knowledge.js — lightweight retrieval layer (BM25-lite) over chatbot-content/*.md
//
// The corpus is generated by scripts/export-chatbot-content.mjs and ships with
// the repository. Files are indexed in heading-sized chunks on first use.
// Features:
//   • synonym expansion ("won"→"winners", "when"→dates/schedule, …)
//   • query-coverage weighting (multi-keyword chunks outrank boilerplate)
//   • entity anchoring (chunks containing rare explicit subject terms win)
//   • per-file URL/Source metadata kept for the model but excluded from scoring
// The retriever fails gracefully (empty results) if the corpus is missing.
// ─────────────────────────────────────────────────────────────────────────────
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const CORPUS_CANDIDATES = [
  path.resolve(__dirname, "../../chatbot-content"),          // repo root (normal layout)
  path.resolve(process.cwd(), "chatbot-content"),             // cwd at repo root
  path.resolve(process.cwd(), "..", "chatbot-content"),       // cwd inside backend/
];

// BM25-lite constants
const K1 = 1.4;
const B = 0.75;
const DEFAULT_TOP_K = 6;
// 0.6 keeps weak synonym-only hits (e.g. "topped the leaderboard" bridging to
// the "winners of …" section) inside the LLM context; entity anchoring and the
// char cap keep the resulting noise cheap.
const MIN_SCORE = 0.6;
const MAX_CHUNK_CHARS = 1100; // keeps RAG input tokens inside the Groq free-tier minute budget

const STOPWORDS = new Set(
  ("a an and are as at be but by can could do does doing for from get got had has have how i in is it its " +
    "me my of on or our out she he they them their the this that to too us was we were which who whom " +
    "will with would you your are am been being about after again all also any because what tell " +
    "been before being both did each here him his if into just more most no nor not now only other own same " +
    "so some such than then there these till up very was well yes").split(" ")
);

// Question words ("when", "where") stay tokens and are expanded onto corpus
// vocabulary so "when is bytebrawl" / "where is x held" reach the logistics
// chunks, and "won/winners" style queries reach the results chunks.
const SYNONYMS = {
  won: ["winner", "winners"],
  win: ["winners", "winner"],
  winners: ["winner", "won"],
  winner: ["winners", "won"],
  results: ["result", "winners", "standings"],
  result: ["results", "winners"],
  standings: ["winners", "results", "leaderboard"],
  leaderboard: ["winners", "standings"],
  topped: ["winners", "standings", "champions"],
  top: ["winners", "standings", "champions"],
  champions: ["winners", "winner"],
  champion: ["winners", "winner"],
  triumphed: ["winners", "winner"],
  when: ["date", "dates", "schedule", "timings", "logistics", "timeline"],
  where: ["venue", "location", "place"],
  held: ["venue", "location"],
  place: ["venue", "location"],
  venue: ["location", "held"],
  location: ["venue"],
  register: ["registration", "registers", "registered"],
  registered: ["registration"],
  registration: ["register", "registered"],
  prize: ["prizes", "rewards"],
  prizes: ["prize", "rewards", "winners"],
  rewards: ["prize", "prizes"],
  fee: ["fees", "cost", "pricing"],
  fees: ["fee", "cost", "pricing"],
  cost: ["fee", "fees", "pricing"],
  free: ["fee", "fees", "cost"],
  speaker: ["speakers", "sessions", "schedule"],
  speakers: ["speaker", "sessions"],
  contact: ["email", "location"],
  email: ["contact"],
  team: ["members", "roster", "committee"],
  members: ["team", "roster"],
  roster: ["team", "members"],
  committee: ["team", "members"],
  president: ["leadership", "team"],
  join: ["induction", "inductions", "eligibility", "recruitment"],
  joining: ["join", "induction", "inductions"],
  induction: ["inductions", "join", "recruitment"],
  inductions: ["induction", "join"],
  eligibility: ["eligible", "join"],
  eligible: ["eligibility", "join"],
  wing: ["wings"],
  wings: ["wing"],
  faculty: ["mentors", "professors", "mentor"],
  mentors: ["faculty", "mentor"],
  mentor: ["mentors", "faculty"],
  problems: ["problem", "statements"],
  problem: ["problems", "statements"],
  statement: ["statements"],
  statements: ["statement", "problem"],
  ideas: ["idea", "projects"],
  idea: ["ideas", "projects"],
  project: ["projects"],
  projects: ["project"],
  tracks: ["track"],
  track: ["tracks"],
  domain: ["domains"],
  domains: ["domain"],
};

/** Per-file metadata lines (URL deep links / provenance), e.g.
 *  "**URL Path:** /events/bytebrawl-hacktoberfest" */
const META_PATTERN = /^(\*\*)?(URL Path|Source|Event Page|Page URL|Website Section)\b[:\s]/i;

function tokenize(text) {
  return String(text)
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9\-\s]+/g, " ")
    .split(/\s+/)
    .filter((t) => t.length >= 2 && !/^\d+$/.test(t) && !STOPWORDS.has(t));
}

function locateCorpus() {
  for (const candidate of CORPUS_CANDIDATES) {
    try {
      if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) return candidate;
    } catch {
      // try next
    }
  }
  return null;
}

/**
 * Splits a markdown document into heading-scoped sections while collecting
 * the per-file metadata lines (URL deep links / provenance) out of the body.
 * Returns { meta: string|null, sections: [{ heading, text }] }.
 */
function extractDocMeta(raw) {
  const metaLines = [];
  const contentLines = [];
  for (const line of String(raw).split(/\r?\n/)) {
    const trimmed = line.trim();
    if (trimmed && META_PATTERN.test(trimmed)) metaLines.push(trimmed);
    else contentLines.push(line);
  }

  const sections = [];
  let heading = null;
  let buf = [];
  const flush = () => sections.push({ heading, text: buf.join("\n") });

  for (const line of contentLines) {
    const headingMatch = line.match(/^#{1,6}\s+(.*)$/);
    if (headingMatch) {
      flush();
      heading = (headingMatch[1] || "").trim() || heading;
      buf = [];
    } else {
      buf.push(line);
    }
  }
  flush();

  return { meta: metaLines.length ? metaLines.join("\n") : null, sections };
}

/** Splits oversized sections on paragraph boundaries. */
function splitLong(text, maxChars) {
  if (text.length <= maxChars) return [text];
  const paragraphs = text.split(/\n\s*\n/);
  const parts = [];
  let acc = "";
  for (const p of paragraphs) {
    const next = acc ? `${acc}\n\n${p}` : p;
    if (next.length > maxChars && acc) {
      parts.push(acc);
      acc = p;
    } else {
      acc = next;
    }
  }
  if (acc) parts.push(acc);
  return parts;
}

let cache; // undefined = not attempted yet; null = attempted and failed

function ensureIndex() {
  if (cache !== undefined) return cache;
  cache = null;
  try {
    const corpusDir = locateCorpus();
    if (!corpusDir) {
      console.warn("[knowledge] chatbot-content/ corpus not found — retrieval disabled (canned replies still work).");
      return cache;
    }

    const files = fs
      .readdirSync(corpusDir)
      .filter((f) => f.toLowerCase().endsWith(".md"))
      .sort();

    const chunks = [];
    for (const file of files) {
      let raw;
      try {
        raw = fs.readFileSync(path.join(corpusDir, file), "utf8");
      } catch {
        continue;
      }
      const docTitleMatch = raw.match(/^#\s+(.+)$/m);
      const docTitle = docTitleMatch ? docTitleMatch[1].trim() : file.replace(/\.md$/i, "").replace(/[-_]+/g, " ");

      const { meta, sections } = extractDocMeta(raw);

      for (const section of sections) {
        const body = section.text.replace(/\n{3,}/g, "\n\n").trim();
        if (!body) continue;
        const title =
          section.heading && section.heading.toLowerCase() !== String(docTitle).toLowerCase()
            ? `${docTitle} — ${section.heading}`
            : docTitle;

        for (const part of splitLong(body, MAX_CHUNK_CHARS)) {
          chunks.push({
            title,
            heading: section.heading,
            // Metadata stays visible to the model (gives it exact deep links)
            // but is excluded from the scoring tokens below.
            text: meta ? `${meta}\n${part}` : part,
            tokens: tokenize(`${title} ${part}`),
          });
        }
      }
    }

    // Build the inverted index
    const postings = new Map(); // term → Map<chunkIndex, termFreq>
    let totalLen = 0;
    chunks.forEach((chunk, i) => {
      chunk.len = Math.max(1, chunk.tokens.length);
      totalLen += chunk.len;
      chunk.titleTokens = new Set(tokenize(chunk.title));

      const counts = new Map();
      for (const term of chunk.tokens) counts.set(term, (counts.get(term) || 0) + 1);
      for (const [term, tf] of counts) {
        let plist = postings.get(term);
        if (!plist) postings.set(term, (plist = new Map()));
        plist.set(i, tf);
      }
    });

    cache = {
      dir: corpusDir,
      chunks,
      postings,
      avgLen: chunks.length ? totalLen / chunks.length : 1,
      fileCount: files.length,
    };
    console.log(`[knowledge] indexed ${chunks.length} sections from chatbot-content/ (${files.length} files) — retrieval online.`);
  } catch (err) {
    console.warn("[knowledge] corpus indexing failed — retrieval disabled:", err && err.message);
    cache = null;
  }
  return cache;
}

/**
 * BM25-lite retrieval. Returns top chunks ranked by relevance:
 * [{ title, heading, text, score }]
 */
export function retrieve(query, { topK = DEFAULT_TOP_K, minScore = MIN_SCORE } = {}) {
  const index = ensureIndex();
  if (!index || !index.chunks.length) return [];

  const qTokens = tokenize(query);
  if (!qTokens.length) return [];

  const N = index.chunks.length;
  const scores = new Float64Array(N);
  const coverage = new Float64Array(N); // distinct original terms matched per chunk

  const bm25 = (idf, tf, chunkIndex) => {
    const chunk = index.chunks[chunkIndex];
    return (idf * tf * (K1 + 1)) / (tf + K1 * (1 - B + B * (chunk.len / index.avgLen)));
  };

  const uniqueQueryTerms = [...new Set(qTokens)];

  // "Entity" terms: explicit enough subjects (bytebrawl, she-leads, ps-13, a
  // team name…) that only a small share of chunks mention. Anchoring makes
  // chunks containing them outrank generic-keyword matches.
  const rareCutoff = Math.max(3, Math.ceil(N * 0.3));
  const entityTerms = uniqueQueryTerms.filter((t) => {
    const plist = index.postings.get(t);
    return plist && plist.size > 0 && plist.size <= rareCutoff;
  });

  // Pass 1: original query terms (drives coverage weighting too)
  for (const term of uniqueQueryTerms) {
    const plist = index.postings.get(term);
    if (!plist) continue;
    const df = plist.size;
    const idf = Math.log(1 + (N - df + 0.5) / (df + 0.5));
    if (idf <= 0) continue;

    for (const [chunkIndex, tf] of plist) {
      scores[chunkIndex] += bm25(idf, tf, chunkIndex);
      coverage[chunkIndex] += 1;
      if (index.chunks[chunkIndex].titleTokens.has(term)) scores[chunkIndex] += idf * 1.2;
    }
  }

  // Pass 2: synonym/question-word expansions to bridge vocabulary gaps
  for (const term of uniqueQueryTerms) {
    for (const synonym of SYNONYMS[term] || []) {
      const plist = index.postings.get(synonym);
      if (!plist) continue;
      const df = plist.size;
      const idf = Math.log(1 + (N - df + 0.5) / (df + 0.5));
      if (idf <= 0) continue;

      for (const [chunkIndex, tf] of plist) {
        scores[chunkIndex] += bm25(idf, tf, chunkIndex) * 0.6;
        if (index.chunks[chunkIndex].titleTokens.has(synonym)) scores[chunkIndex] += idf * 0.4;
      }
    }
  }

  // Coverage weighting: chunks matching a larger share of the query's own
  // vocabulary outrank single-keyword boilerplate matches.
  const uniqueTermCount = Math.max(1, uniqueQueryTerms.length);
  for (let i = 0; i < N; i++) {
    if (scores[i] <= 0) continue;
    const covered = Math.min(1, coverage[i] / uniqueTermCount);
    scores[i] *= 0.55 + 0.45 * covered;
  }

  // Entity anchoring: +30% for chunks containing any explicit entity term,
  // −40% for chunks that only matched via generic expansions.
  if (entityTerms.length) {
    const anchored = new Uint8Array(N);
    for (const term of entityTerms) {
      for (const [chunkIndex] of index.postings.get(term)) anchored[chunkIndex] = 1;
    }
    for (let i = 0; i < N; i++) {
      if (scores[i] <= 0) continue;
      scores[i] *= anchored[i] ? 1.3 : 0.6;
    }
  }

  const scored = [];
  for (let i = 0; i < N; i++) {
    if (scores[i] >= minScore) {
      const chunk = index.chunks[i];
      scored.push({ title: chunk.title, heading: chunk.heading, text: chunk.text, score: scores[i] });
    }
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, topK);
}

export function corpusReady() {
  const index = ensureIndex();
  return Boolean(index && index.chunks.length);
}

export function corpusStats() {
  const index = cache === undefined ? ensureIndex() : cache;
  return {
    ready: Boolean(index && index.chunks.length),
    sections: index ? index.chunks.length : 0,
  };
}
